"""Checkpoint Trunk + 802.1Q: conteúdo estruturado e feedback por hipótese."""


def token(key, text): return {"id": key, "text": text}
def slot(key, label, many=False):
    value = {"id": key, "label": label}
    if many: value["capacity"] = "many"
    return value


